/* 按语言返回当前注入/校验用的约束句；zh 用中文版，en/mixed 用英文版。 */
function fixedCameraConstraint() { return lang() === 'zh' ? FIXED_CAMERA_CONSTRAINT_ZH : FIXED_CAMERA_CONSTRAINT; }
function visualStabilityConstraint() { return lang() === 'zh' ? VISUAL_STABILITY_CONSTRAINT_ZH : VISUAL_STABILITY_CONSTRAINT; }
function noSubtitlesConstraint() { return lang() === 'zh' ? NO_SUBTITLES_CONSTRAINT_ZH : NO_SUBTITLES_CONSTRAINT; }
/* Ref2VA 替换类任务强化规则（2026-09-02 实测教训）。
   失败案例：单 Subject 定义 + "used to replace" 一句带过 + 大段"不得改变"否定句占据正文 → 模型只替换首帧。
   成功对照（豆包）：替换来源与被保留元素分两个 Subject；retention 写明继承特征并执行原角色整套动作；
   detailed_description 用肯定语气把替换写成正文核心，并明确贯穿全片每一帧。 */
const REF2VA_REPLACE_RE = /替换|换成|替代|更换|换掉|replace|swap|substitute/i;
const REF2VA_REPLACE_INSTR = '【替换类任务强化规则】本任务是用参考素材中的人物/物体替换源视频中的某个元素，除上述格式外必须遵守：' +
  '① subject_definitions 至少三行：<Subject N> 为替换来源（如 <Picture 1> 中的人物），写出要继承的具体外貌特征（脸型五官、发型、体型、服装）；<Subject M> 定义源视频 <Video N> 中的被替换角色或需完整保留的整体内容（场景环境、构图、镜头运动、其余人物），若定义被替换角色，写明其作用只是动作与节奏模板（身体动作、姿态、转头、面部微动作与时机原样保留），其外貌不再出现在目标视频中；<Video N> 再单独一行写 is the source video for the target video edit.。<Picture N> 首选只出现在 <Subject N> 的定义句中作为来源，不要在 summary、retention_analysis 或 detailed_description 中引用；不要只写一句 used to replace 带过替换用途。' +
  '② summary 以任务类型前缀开头，随后先写 The target video is an edited version of <Video N>.，再明确写：将源视频中的被替换者替换为 <Subject N>，<Subject N> 的外貌在全部帧保持一致，并完整执行原角色的全部动作，其余所有元素保持不变；summary 只引用已定义的 <Subject N>/<Subject M>/<Video N> 标签。' +
  '③ retention_analysis：<Subject N> 用 attribute_transfer，直接写继承的具体外貌特征，并写明执行原角色的整套身体动作、姿态、转头与面部微动作（动作节奏与时机与源视频严格一致）；<Subject M> 若定义为动作模板，写 fully_preserved - 仅保留原角色的动作、姿态与时机并由 <Subject N> 执行，其外貌不再出现；若定义为保留内容，逐项列出；<Video N> 写一行结构保留，如 (source structure): fully_preserved - shot structure, pacing and timing are retained, only the character is replaced。' +
  '④ detailed_description 的核心是替换动作本身，全部用肯定语气描述全片实际发生什么：[Shot 1] 之前先写一句继承源视频原有光线与色调的风格句；[Shot 1] 内写 <Subject N> 从第一帧到最后一帧替换原角色，逐项执行原角色的身体动作、姿态、转头与面部微动作，动作节奏与时机与源视频严格一致；随后逐项写其余元素保持原样。明确写出替换与外貌一致性贯穿整个视频的每一帧，绝不能只替换首帧。禁止用成段的 不得…/禁止… 否定句占据正文；固定镜头与画面稳定约束各最多写一句并放在替换描述之后。引用标签首选只用 <Subject N>/<Subject M>/<Video N>。' +
  '⑤ 自检：summary、retention_analysis、detailed_description 中出现的每个标签都必须能在 subject_definitions 中找到（独立定义行或定义句内的来源引用），独立定义的每个标签都必须在 retention_analysis 有对应行。';
function ref2vaReplaceInstr(isZh) {
  if (!isZh) return REF2VA_REPLACE_INSTR;
  return REF2VA_REPLACE_INSTR
    .replace('is the source video for the target video edit.', '是目标视频编辑所用的源视频。')
    .replace('The target video is an edited version of <Video N>.', '目标视频是 <Video N> 的编辑版本。')
    .replace('(source structure): fully_preserved - shot structure, pacing and timing are retained, only the character is replaced', '（源结构）：fully_preserved - 镜头结构、节奏与时机保持不变，仅替换人物');
}
