function generate() {
  const mode = getMode();
  const dur = duration();
  let out = '';
  if (mode === 't2va')    out = genT2VA();
  else if (mode === 'i2va')   out = genI2VA(dur);
  else if (mode === 'fl2va')  out = genFL2VA(dur);
  else if (mode === 'l2va')   out = genL2VA(dur);
  else if (mode === 'ref2va') out = genRef2VA();
  out = normalizeInlineDialogue(out);
  out = normalizeEmptyShot1Punctuation(out);
  out = applyFixedCameraConstraint(out);
  out = applyVisualStabilityConstraint(out);
  $('output').value = out.trim() + '\n';
  updateFormatNotice();
  const words = countWords(out.trim());
  const constraintError = promptConstraintError(out, mode);
  const advisory = (mode === 'ref2va' && $('enrich_do_enrich') && $('enrich_do_enrich').checked) ? ref2vaWordAdvisory(out) : '';
  if (constraintError) console.warn('[H3 validation][manual output]', constraintError);
  if (advisory) console.warn('[H3 validation][advisory]', advisory);
  $('statLine').textContent = constraintError
    ? `模式：${MODE_META[mode].name} · ${formatLabel()} · 时长：${dur}s · ${out.trim().length} 字符 · 约 ${words} 词`
    : `模式：${MODE_META[mode].name} · ${formatLabel()} · 语言：${langLabel()} · 时长：${dur}s · 宽高比：${$('ratio').value} · ${out.trim().length}/${H3_MAX_PROMPT_CHARS} 字符 · 约 ${words} 词`;
}

/* ---- T2VA ---- */
function genT2VA() {
  const style = getStyle('f_style','f_style_custom');
  const scene = $('f_scene').value.trim();
  const ss    = $('f_soundscape').value.trim();
  const mu    = $('f_music').value.trim();
  const isZh  = lang() === 'zh';
  const sep   = isZh ? '，' : ', ';

  let imd;
  if (/^\[Shot 1\]/.test(scene)) {
    imd = `integrated_multimodal_description: ${scene}`;
  } else {
    imd = `integrated_multimodal_description: [Shot 1] ${[style, scene].filter(Boolean).join(sep)}`;
  }
  return `${imd}\n\noverall_soundscape: ${selectedSoundscape(ss)}\n\nnon_diegetic_music: ${selectedMusic(mu)}`;
}

/* ---- I2VA ---- */
function genI2VA() {
  const style = getStyle('i2_style','i2_style_custom');
  const first = $('i2_first').value.trim();
  const act   = $('i2_action').value.trim();
  const ss    = $('i2_soundscape').value.trim();
  const mu    = $('i2_music').value.trim();
  const isZh  = lang() === 'zh';
  const sep   = isZh ? '，' : ', ';
  /* zh 也识别中文时间段（秒：）与「被完整保留」，与 en 的回传判定等价（2026-09-23 修复） */
  const aiRoundTrip = /<Picture 1>/i.test(act) && (/(?:^|\s)\d+(?:\.\d+)?\s*[-–—‑]\s*\d+(?:\.\d+)?\s*(?:s|秒)\s*[：:]/.test(act) || /fully preserved|被完整保留/i.test(act));
  const keepLead = isZh ? '<Picture 1> 中的主体与构图被完整保留' : 'the subject and composition shown in <Picture 1> are fully preserved';
  const detail = aiRoundTrip ? joinStyleWithRoundTrip(style, stripRoundTripGlobalConstraints(act), sep) : [first ? `${keepLead}${isZh ? '：' : ': '}${first}` : keepLead, act].filter(Boolean).join(sep);
  return `${i2vaAlignLine()}\n\nintegrated_multimodal_description: [Shot 1] ${aiRoundTrip ? detail : style + (detail ? sep + detail : '')}\n\noverall_soundscape: ${selectedSoundscape(ss)}\n\nnon_diegetic_music: ${selectedMusic(mu)}`;
}

/* ---- FL2VA ---- */
function genFL2VA(dur) {
  const style = getStyle('fl_style','fl_style_custom');
  const first = $('fl_first').value.trim();
  const last  = $('fl_last').value.trim();
  const path  = $('fl_path').value.trim();
  const ss    = $('fl_soundscape').value.trim();
  const mu    = $('fl_music').value.trim();
  const isZh  = lang() === 'zh';
  const sep   = isZh ? '，' : ', ';

  const detail = path || (isZh ? '画面主体从首帧姿态连续运动到最后帧姿态' : 'The visible subject moves continuously from the first-frame pose to the last-frame pose');
  const aiRoundTrip = /Picture 1/i.test(path) && /Picture 2/i.test(path);
  /* 连接短语按语言生成；Picture 1/Picture 2 为技术 token 保持英文（2026-09-23 修复） */
  const openLead = isZh ? '开场状态遵循 Picture 1' : 'the opening state follows Picture 1';
  const settleLead = isZh ? '运动在结尾精确落定为 Picture 2 的状态与构图' : 'the motion settles into the exact state and composition of Picture 2 at the end';
  const body = aiRoundTrip ? joinStyleWithRoundTrip(style, stripRoundTripGlobalConstraints(path), sep) : [style, first ? `${openLead}${isZh ? '：' : ': '}${first}` : openLead, detail, last ? `${settleLead}${isZh ? '：' : ': '}${last}` : settleLead].filter(Boolean).join(sep);
  return `${fl2vaAlignLine(1, dur)}\n\nintegrated_multimodal_description: [Shot 1] ${body}\n\noverall_soundscape: ${selectedSoundscape(ss)}\n\nnon_diegetic_music: ${selectedMusic(mu)}`;
}

/* ---- L2VA ---- */
function genL2VA(dur) {
  const style  = getStyle('l2_style','l2_style_custom');
  const last   = $('l2_last').value.trim();
  const open   = $('l2_opening').value.trim();
  const path   = $('l2_path').value.trim();
  const ss     = $('l2_soundscape').value.trim();
  const mu     = $('l2_music').value.trim();
  const isZh   = lang() === 'zh';
  const sep    = isZh ? '，' : ', ';

  const detail = [open, path].filter(Boolean).join(sep) || (isZh ? '画面主体自然发展并收敛到所提供的尾帧' : 'The visible subject develops naturally toward the supplied last frame');
  /* zh 不扩展回传判定（落定/构图/最终 等词过于宽泛，会误吞 l2_opening）；仅本地化连接短语（2026-09-23 修复） */
  const aiRoundTrip = /<Picture 1>/i.test(path) && /(?:settle|composition|final|end)/i.test(path);
  const settleLead = isZh ? '运动元素在结尾精确落定为 <Picture 1> 所确立的状态与构图' : 'the moving elements settle into the exact state and composition established by <Picture 1> at the end';
  const body = aiRoundTrip ? joinStyleWithRoundTrip(style, stripRoundTripGlobalConstraints(path), sep) : [style, detail, last ? `${settleLead}${isZh ? '：' : ': '}${last}` : settleLead].filter(Boolean).join(sep);
  return `${l2vaAlignLine(1, dur)}\n\nintegrated_multimodal_description: [Shot 1] ${body}\n\noverall_soundscape: ${selectedSoundscape(ss)}\n\nnon_diegetic_music: ${selectedMusic(mu)}`;
}

/* ---- Ref2VA ---- */
function genRef2VA() {
  const subj = $('r_subject').value.trim();
  const sum  = $('r_summary').value.trim();
  const ret  = $('r_retention').value.trim();
  const det  = $('r_detail').value.trim();
  const ss   = $('r_soundscape').value.trim();
  const mu   = $('r_music').value.trim();

  const types = Array.from(document.querySelectorAll('#r_tasktypes input:checked')).map(i => i.value);
  const prefix = types.length ? '[' + types.join(' + ') + '] ' : '[reference generation] ';

  return `subject_definitions:\n${subj}\n\nsummary:\n${prefix}${sum}\n\nretention_analysis:\n${ret}\n\ndetailed_description:\n${det}\n\noverall_soundscape:\n${selectedSoundscape(ss)}\n\nnon_diegetic_music:\n${selectedMusic(mu)}`;
}

/* ==================== 提示气泡（tip）：说明文字不占布局，悬浮/聚焦/点击时弹出 ==================== */
(function initTips() {
  /* 无头沙箱（回归测试）下不存在完整 document，直接跳过 */
  if (!document || typeof document.addEventListener !== 'function' ||
      typeof document.createElement !== 'function' || !document.body) return;
  let bubble = null;
  let current = null;
  const SEL = '[data-tip]';
  function bubbleEl() {
    if (!bubble) {
      bubble = document.createElement('div');
      bubble.id = 'tipBubble';
      bubble.setAttribute('role', 'tooltip');
      document.body.appendChild(bubble);
    }
    return bubble;
  }
  function targetOf(e) {
    const t = e.target;
    return (t instanceof Element) ? t.closest(SEL) : null;
  }
  function place() {
    if (!current || !bubble) return;
    const r = current.getBoundingClientRect();
    const br = bubble.getBoundingClientRect();
    const gap = 8;
    const maxLeft = Math.max(gap, window.innerWidth - br.width - gap);
    let left = r.left + r.width / 2 - br.width / 2;
    left = Math.max(gap, Math.min(left, maxLeft));
    let top = r.top - br.height - gap;
    if (top < gap) top = Math.min(r.bottom + gap, window.innerHeight - br.height - gap);
    bubble.style.left = Math.round(left) + 'px';
    bubble.style.top = Math.round(Math.max(gap, top)) + 'px';
  }
  function show(target) {
    const html = target.getAttribute('data-tip');
    if (!html) return;
    hide();
    current = target;
    const b = bubbleEl();
    b.innerHTML = html;
    b.classList.add('show');
    place();
  }
  function hide() {
    if (bubble) bubble.classList.remove('show');
    current = null;
  }
  document.addEventListener('mouseover', e => { const t = targetOf(e); if (t) show(t); });
  document.addEventListener('mouseout', e => { const t = targetOf(e); if (t && t === current) hide(); });
  document.addEventListener('focusin', e => { const t = targetOf(e); if (t) show(t); });
  document.addEventListener('focusout', e => { const t = targetOf(e); if (t && t === current) hide(); });
  document.addEventListener('click', e => {
    const t = targetOf(e);
    if (t) { show(t); e.preventDefault(); } else { hide(); }
  });
  document.addEventListener('keydown', e => { if (e.key === 'Escape') hide(); });
  window.addEventListener('scroll', () => { if (current) place(); }, true);
  window.addEventListener('resize', hide);
  window.addEventListener('blur', hide);
})();

/* ==================== 模式切换 ==================== */
function onModeChange() {
  const mode = getMode();
  document.querySelectorAll('.mode-fields').forEach(el => {
    el.hidden = el.dataset.mode !== mode;
  });
  const modeTip = $('modeTip');
  if (modeTip && typeof modeTip.setAttribute === 'function') {
    modeTip.setAttribute('data-tip', `<b>${MODE_META[mode].name}</b> — ${MODE_META[mode].desc}`);
  }
  generate();
}
function onLangChange() {
  try { localStorage.setItem(LANG_KEY, lang()); } catch (e) {}
  const out = $('output');
  if (out && out.value.trim()) {
    out.value = rebuildVisualConstraints(normalizeKeyframeAlignment(getMode(), out.value));
    const error = finalPromptError(out.value, getMode());
    setAiResultNotice(error ? 'invalid' : 'valid', error);
    refreshStatLine();
  } else generate();
  showToast('🌐 语言：' + langLabel() + '；现有正文已保留，需要翻译时请重新生成');
}

/* ==================== 复制 / 下载 ==================== */
function showToast(msg) {
  const t = $('toast');
  t.textContent = msg;
  t.classList.add('show');
  clearTimeout(showToast._timer);
  showToast._timer = setTimeout(() => t.classList.remove('show'), 1800);
}
function setAiResultNotice(status, reason) {
  const notice = $('aiResultNotice');
  if (!notice) return;
  if (reason) console.warn('[H3 validation][' + status + ']', reason);
  if (status === 'warning' || status === 'invalid' || status === 'error') {
    status = 'notice';
  }
  notice.style.display = '';
  notice.className = 'callout' + (status === 'valid' ? ' callout-green' : '');
  const messages = {
    running: '🤖 <b>AI 正在生成：</b>完成后请检查正文与对白语言、格式类型、勾选项和 H3 结构。',
    valid: '✅ <b>自动校验已通过：</b>结果已通过当前结构与语言规则检查。AI 仍具有随机性，请快速核对画面语义、对白内容和声源归属；如不满意，请再次点击「✨ 自动生成」。',
    notice: '💡 <b>AI 结果提示：</b>AI 生成具有一定随机性。使用前建议快速核对画面语义、声源归属、对白内容和时间安排；如不满意，可修改结果或再次点击「✨ 自动生成」。',
    warning: '💡 <b>AI 结果提示：</b>AI 生成具有一定随机性。使用前建议快速核对画面语义、声源归属、对白内容和时间安排。',
    invalid: '💡 <b>AI 结果提示：</b>AI 生成具有一定随机性。使用前建议快速核对画面语义、声源归属、对白内容和时间安排。',
    partial: '⚠️ <b>当前是部分结果：</b>生成已停止或超时，请检查并手动补全，或再次点击「✨ 自动生成」。',
    offline: '💡 <b>离线结果：</b>输入正文已按原样保留并包装为所选 H3 结构；请按需要检查和微调。'
  };
  notice.innerHTML = messages[status] || messages.invalid;
}

const DEFAULT_SOUNDSCAPE_EN = 'Subtle ambient sound appropriate to the depicted environment continues throughout the video.';
const DEFAULT_SOUNDSCAPE_ZH = '贴合画面环境的环境声自然延续，音量克制。';
const DEFAULT_MUSIC_EN = 'A restrained solo piano score at a slow tempo, with steady, widely spaced notes and quiet dynamics that fade out gently.';
const DEFAULT_MUSIC_ZH = '慢速而克制的钢琴独奏，音符间距宽松，动态轻柔，结尾缓缓淡出。';
function selectedSoundscape(value) {
  return $('enrich_soundscape').checked ? (String(value || '').trim() || (lang() === 'zh' ? DEFAULT_SOUNDSCAPE_ZH : DEFAULT_SOUNDSCAPE_EN)) : 'N/A';
}
function selectedMusic(value) {
  return $('enrich_music').checked ? (String(value || '').trim() || (lang() === 'zh' ? DEFAULT_MUSIC_ZH : DEFAULT_MUSIC_EN)) : 'N/A';
}

/* 校验分级：仅确定会破坏结构或丢失内容的问题判为 error；AI 表达差异和质量契约作为 warning。 */
function validationIssueLevel(reason) {
  const r = String(reason || '');
  if (!r) return 'valid';
  return /说话人 ID|正文出现中文|正文出现英文|正文必须使用中文|描述必须使用英文|section 必须使用英文|音景或配乐(?:描述|的句数|与勾选项)|扩写过多|固定镜头|固定机位约束|画面稳定|防闪烁|色温漂移|自动时间戳|未生成任何 At|镜头运动|切镜描述/i.test(r)
    ? 'warning' : 'error';
}
/* 复制/下载成功后按当前输出刷新状态栏，清掉上一次校验的残留提示。 */
function refreshStatLine() {
  const out = ($('output').value || '').trim();
  const words = countWords(out);
  const constraintError = promptConstraintError(out, getMode());
  if (constraintError) console.warn('[H3 validation][status]', constraintError);
  $('statLine').textContent = constraintError
    ? '模式：' + MODE_META[getMode()].name + ' · ' + out.length + ' 字符 · 约 ' + words + ' 词'
    : '模式：' + MODE_META[getMode()].name + ' · ' + formatLabel() + ' · 语言：' + langLabel() + ' · 时长：' + duration() + 's · 宽高比：' + $('ratio').value + ' · ' + out.length + '/' + H3_MAX_PROMPT_CHARS + ' 字符 · 约 ' + words + ' 词';
}
function copyOutput() {
  const ta = $('output');
  const error = finalPromptError(ta.value, getMode());
  const issueLevel = validationIssueLevel(error);
  if (error) {
    console.warn('[H3 validation][copy]', error);
    refreshStatLine();
    setAiResultNotice(issueLevel, error);
  } else {
    refreshStatLine();
  }
  if (navigator.clipboard && window.isSecureContext) {
    navigator.clipboard.writeText(ta.value)
      .then(() => showToast('✅ 已复制到剪贴板'))
      .catch(() => fallbackCopy(ta));
  } else {
    fallbackCopy(ta);
  }
}
function fallbackCopy(ta) {
  ta.select();
  ta.setSelectionRange(0, ta.value.length);
  try { document.execCommand('copy'); showToast('✅ 已复制到剪贴板'); }
  catch (e) { showToast('❌ 复制失败，请手动 Ctrl+C'); }
}
function downloadOutput() {
  const text = $('output').value;
  const error = finalPromptError(text, getMode());
  const issueLevel = validationIssueLevel(error);
  if (error) {
    console.warn('[H3 validation][download]', error);
    refreshStatLine();
    setAiResultNotice(issueLevel, error);
  } else {
    refreshStatLine();
  }
  const blob = new Blob([text], { type: 'text/plain;charset=utf-8' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `h3-prompt-${getMode()}-${lang()}-${duration()}s.txt`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(a.href);
  showToast('⬇️ 已下载 .txt');
}

/* ==================== 独立 AI 全文翻译 ==================== */
let translationAbortCtrl = null;
let translationSourceSnapshot = '';
let translationStopped = false;
let translationTimedOut = false;
let translationRunId = 0;
function openTranslationModal() {
  const source = $('output').value;
  if (!source.trim()) { showToast('请先生成或填写提示词'); return; }
  translationSourceSnapshot = source;
  if (translationAbortCtrl) translationAbortCtrl.abort();
  translationAbortCtrl = null;
  translationRunId++;
  translationStopped = false;
  translationTimedOut = false;
  $('translation_output').value = '';
  $('copyTranslationBtn').disabled = true;
  $('translateBtn').disabled = false;
  $('stopTranslateBtn').style.display = 'none';
  $('translationModal').classList.add('open');
  $('translationStatus').textContent = '已读取当前结果快照。翻译不会修改原始提示词。';
}
function closeTranslationModal() {
  translationStopped = true;
  translationRunId++;
  if (translationAbortCtrl) translationAbortCtrl.abort();
  translationAbortCtrl = null;
  $('translateBtn').disabled = false;
  $('stopTranslateBtn').style.display = 'none';
  $('translationModal').classList.remove('open');
}
function stopTranslation() {
  if (!translationAbortCtrl) return;
  translationStopped = true;
  translationAbortCtrl.abort();
}
function cleanTranslationResult(text) {
  return String(text || '').trim().replace(/^```(?:text)?\s*/i, '').replace(/\s*```$/, '').trim();
}
function structureTokenCounts(text) {
  const t = String(text || '');
  const patterns = {
    references: /<(?:Picture|Subject|Video|Audio)\s+\d+>/g,
    shots: /\[Shot\s+\d+\]/g,
    speakers: /\(S\d+(?:\s*,\s*S\d+)*\)/g,
    timestamps: /(?:\bAt\s+\d{2}:\d{2}\.\d{3}\b|\b\d+(?:\.\d+)?\s*[-–—‑]\s*\d+(?:\.\d+)?s\s*:)/g,
    fields: /(?:^|\n)(?:integrated_multimodal_description|overall_soundscape|non_diegetic_music|subject_definitions|summary|retention_analysis|detailed_description):/g
  };
  return Object.fromEntries(Object.entries(patterns).map(([name, re]) => [name, (t.match(re) || []).length]));
}
function translationStructureWarning(source, translated) {
  const a = structureTokenCounts(source), b = structureTokenCounts(translated);
  const changed = Object.keys(a).filter(name => a[name] !== b[name]);
  return changed.length ? '提醒：译文中的结构标识数量发生变化（' + changed.join('、') + '），请人工核对。' : '';
}
async function startTranslation() {
  if (translationAbortCtrl) return;
  const source = translationSourceSnapshot || $('output').value;
  if (!source.trim()) { $('translationStatus').textContent = '原始结果为空，无法翻译。'; return; }
  const key = currentKey();
  const model = currentModel();
  if (!key) { $('translationStatus').textContent = '当前 AI 模型没有可用密钥。'; return; }
  const target = $('translation_target').value;
  const targetName = target === 'zh' ? 'Simplified Chinese' : 'English';
  const sys = 'You are a precise full-text translator. Translate every natural-language phrase in the supplied text into ' + targetName + ', without distinguishing dialogue from descriptive text. Preserve all field names, <Picture N>/<Subject N>/<Video N>/<Audio N> tags, [Shot N] labels, (S1)/(S2) speaker IDs, timestamps, time ranges, N/A values, punctuation structure, line breaks, paragraph order, and <d> wrappers. Update every [Chinese]/[English] language tag to match the target language. Do not add, omit, summarize, explain, correct, or regenerate any content. Return only the complete translated text with no Markdown fence.';
  const user = 'Target language: ' + targetName + '\n\nText to translate:\n' + source;
  const output = $('translation_output');
  const status = $('translationStatus');
  translationAbortCtrl = new AbortController();
  const controller = translationAbortCtrl;
  const runId = ++translationRunId;
  translationStopped = false;
  translationTimedOut = false;
  output.value = '';
  $('translateBtn').disabled = true;
  $('stopTranslateBtn').style.display = 'inline-flex';
  $('copyTranslationBtn').disabled = true;
  status.textContent = 'AI 正在翻译……';
  const timeoutId = setTimeout(function () { if (runId === translationRunId) { translationTimedOut = true; controller.abort(); } }, 180000);
  try {
    let streamed = '';
    const result = await callLLM(sys, user, key, function (delta) {
      streamed += delta;
      output.value = cleanTranslationResult(streamed);
    }, model.endpoint, model.model, controller.signal, () => translationStopped || translationTimedOut || runId !== translationRunId);
    if (runId !== translationRunId) return;
    output.value = cleanTranslationResult(result);
    if (translationStopped) { status.textContent = '翻译已停止，已保留当前部分译文。'; return; }
    if (translationTimedOut) { status.textContent = '翻译超时，已保留当前部分译文。'; return; }
    const warning = translationStructureWarning(source, output.value);
    const sourceChanged = $('output').value !== source;
    status.textContent = (warning || '翻译完成。') + (sourceChanged ? ' 原始结果已变化；当前译文基于打开弹窗时的快照。' : ' 译文基于当前原始结果。');
  } catch (e) {
    if (runId !== translationRunId) return;
    if (translationStopped) status.textContent = '翻译已停止，已保留当前部分译文。';
    else if (translationTimedOut) status.textContent = '翻译超时，已保留当前部分译文。';
    else status.textContent = '翻译失败：' + (e && e.message ? e.message : String(e));
  } finally {
    clearTimeout(timeoutId);
    if (runId === translationRunId) {
      translationAbortCtrl = null;
      $('translateBtn').disabled = false;
      $('stopTranslateBtn').style.display = 'none';
      $('copyTranslationBtn').disabled = !$('translation_output').value.trim();
    }
  }
}
function copyTranslation() {
  const ta = $('translation_output');
  if (!ta.value.trim()) { showToast('暂无译文可复制'); return; }
  if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(ta.value).then(() => showToast('✅ 已复制译文')).catch(() => fallbackCopy(ta));
  else fallbackCopy(ta);
}

/* ==================== 示例填充 ==================== */
