/* 多场景匹配：返回命中的所有场景（最多 2 个，供组合融合） */
function detectScenes(raw) {
  const l = raw.toLowerCase();
  const found = [];
  for (const s of SCENE_LIST) {
    if (!s.id || s.id === 'generic') continue;
    for (const k of s.keys) {
      if (l.includes(k)) { found.push(s); break; }
    }
    if (found.length >= 2) break;
  }
  return found.length ? found : [SCENE_LIST[0]];
}

