function syncFeatureAll() {
  const all = $('feature_all');
  if (all) all.checked = ['auto_timestamps', 'fixed_camera', 'visual_stability', 'no_subtitles', 'anti_pop'].every(id => $(id).checked);
}
function onAntiPopChange() {
  try { localStorage.setItem(ANTI_POP_KEY, antiPopOn() ? '1' : '0'); } catch (e) {}
  syncFeatureAll();
  const out = $('output');
  if (!out || !out.value.trim()) { generate(); return; }
  if (antiPopOn()) {
    out.value = normalizeInlineDialogue(out.value);
    setAiResultNotice('notice');
    refreshStatLine();
    showToast('已将当前结果转换为抗残音内联格式');
    return;
  }
  if (/\[(?:Chinese|中文|English)\]/.test(out.value) && !/<d>/.test(out.value)) {
    out.value = normalizeOfficialDialogue(out.value);
    const error = finalPromptError(out.value, getMode());
    setAiResultNotice(error ? 'invalid' : 'valid', error || undefined);
    refreshStatLine();
    showToast('已关闭抗残音并恢复官方 <d> 对白格式');
    return;
  }
  refreshStatLine();
}
function toggleFeatureAll() {
  const previousAntiPop = antiPopOn();
  const checked = $('feature_all').checked;
  ['auto_timestamps', 'fixed_camera', 'visual_stability', 'no_subtitles', 'anti_pop'].forEach(id => { $(id).checked = checked; });
  try {
    localStorage.setItem(AUTO_TIMESTAMPS_KEY, checked ? '1' : '0');
    localStorage.setItem(FIXED_CAMERA_KEY, checked ? '1' : '0');
    localStorage.setItem(VISUAL_STABILITY_KEY, checked ? '1' : '0');
    localStorage.setItem(NO_SUBTITLES_KEY, checked ? '1' : '0');
    localStorage.setItem(ANTI_POP_KEY, checked ? '1' : '0');
  } catch (e) {}
  reconcileCurrentOutputOptions();
  if (previousAntiPop !== checked) onAntiPopChange();
  showToast(checked ? '功能选项已全选' : '功能选项已全不选');
}

/* ==================== 输入提示词历史 ==================== */
const PROMPT_HISTORY_KEY = 'h3-prompt-history-v1';
const PROMPT_HISTORY_LIMIT = 30;
function loadPromptHistory() {
  try {
    const raw = JSON.parse(localStorage.getItem(PROMPT_HISTORY_KEY) || '[]');
    if (!Array.isArray(raw)) return [];
    return raw.map(function (item) {
      if (typeof item === 'string') return { text: item, updatedAt: 0 };
      return item && typeof item.text === 'string' ? { text: item.text, updatedAt: Number(item.updatedAt) || 0 } : null;
    }).filter(item => item && item.text.trim()).slice(0, PROMPT_HISTORY_LIMIT);
  } catch (e) {
    console.warn('[Prompt history] 读取失败', e);
    return [];
  }
}
function storePromptHistory(items) {
  try {
    localStorage.setItem(PROMPT_HISTORY_KEY, JSON.stringify(items.slice(0, PROMPT_HISTORY_LIMIT)));
    return true;
  } catch (e) {
    console.warn('[Prompt history] 保存失败', e);
    return false;
  }
}
function promptHistoryLabel(text) {
  const oneLine = String(text || '').replace(/\s+/g, ' ').trim();
  return oneLine.length > 64 ? oneLine.slice(0, 64) + '…' : oneLine;
}
function renderPromptHistory(activeText) {
  const select = $('prompt_history');
  if (!select) return;
  const items = loadPromptHistory();
  select.replaceChildren();
  const head = document.createElement('option');
  head.value = '';
  head.textContent = '🕘 历史记录（' + items.length + '）';
  select.appendChild(head);
  items.forEach(function (item, index) {
    const option = document.createElement('option');
    option.value = String(index);
    option.textContent = promptHistoryLabel(item.text);
    option.title = item.text;
    select.appendChild(option);
  });
  const active = String(activeText == null ? (($('enrich_input') && $('enrich_input').value) || '') : activeText).trim();
  const activeIndex = items.findIndex(item => item.text === active);
  select.value = activeIndex >= 0 ? String(activeIndex) : '';
  $('deleteHistoryBtn').disabled = activeIndex < 0;
  $('clearHistoryBtn').disabled = !items.length;
}
function savePromptHistory(text) {
  const normalized = String(text || '').trim();
  if (!normalized) return;
  const items = loadPromptHistory().filter(item => item.text !== normalized);
  items.unshift({ text: normalized, updatedAt: Date.now() });
  if (storePromptHistory(items)) renderPromptHistory(normalized);
}
function onPromptHistoryChange() {
  const select = $('prompt_history');
  const index = select && select.value !== '' ? Number(select.value) : -1;
  const items = loadPromptHistory();
  if (!Number.isInteger(index) || index < 0 || index >= items.length) {
    if ($('deleteHistoryBtn')) $('deleteHistoryBtn').disabled = true;
    return;
  }
  $('enrich_input').value = items[index].text;
  $('deleteHistoryBtn').disabled = false;
  showToast('已切换到所选历史提示词');
}
function syncPromptHistorySelection() {
  const select = $('prompt_history');
  if (!select) return;
  const current = $('enrich_input').value.trim();
  const index = loadPromptHistory().findIndex(item => item.text === current);
  select.value = index >= 0 ? String(index) : '';
  $('deleteHistoryBtn').disabled = index < 0;
}
function deleteSelectedPromptHistory() {
  const select = $('prompt_history');
  const index = select && select.value !== '' ? Number(select.value) : -1;
  const items = loadPromptHistory();
  if (!Number.isInteger(index) || index < 0 || index >= items.length) { showToast('请先选择一条历史记录'); return; }
  items.splice(index, 1);
  storePromptHistory(items);
  renderPromptHistory();
  showToast('已删除所选历史记录');
}
function clearPromptHistory() {
  const items = loadPromptHistory();
  if (!items.length) return;
  if (!confirm('确定清空全部输入提示词历史吗？此操作不可撤销。')) return;
  storePromptHistory([]);
  renderPromptHistory();
  showToast('已清空输入提示词历史');
}

async function enrich() {
  const raw = $('enrich_input').value;
  if (!raw.trim()) { showToast('⚠️ 请先输入提示词'); return; }
  savePromptHistory(raw);
  // 默认调用 AI；用户取消勾选「使用 AI」时使用离线模板。
  const useAi = $('enrich_use_ai') && $('enrich_use_ai').checked;
  if (useAi) {
    const key = currentKey();
    if (key) {
      try {
        await runAiEnrich(raw);
        return;
      } catch (e) {
        showToast('❌ ' + currentModel().label + ' 生成失败；为避免输出非合规结果，未自动回退：' + (e.message || e));
        return;
      }
    } else {
      showToast('❌ 当前模型未配置 API Key，无法在线生成所选语言的 H3 结果');
      return;
    }
  }
  runTemplateEnrich(raw);
  setAiResultNotice('offline');
}

function runTemplateEnrich(raw) {
  // 离线模式：正文逐字符原样保留，不翻译、不扩写、不纠正符号，只包装为所选模式的 H3 结构。
  const mode = getMode();
  const sf = STYLE_FIELDS[mode];
  const style = sf ? getStyle(sf[0], sf[1]) : 'Cinematic, live-action';
  const isZh = lang() === 'zh';
  const sep = isZh ? '，' : ', '; // 分隔符跟随所选语言：中文用全角逗号，英文用英文逗号
  const firstLine = /^\[Shot 1\]/.test(raw) ? raw : '[Shot 1] ' + style + sep + raw;
  // 音景/配乐：按勾选项从场景模板生成（模板语言跟随所选语言，无需联网）
  const withSoundscape = $('enrich_soundscape') && $('enrich_soundscape').checked;
  const withMusic = $('enrich_music') && $('enrich_music').checked;
  const scenes = detectScenes(raw);
  const main = scenes[0];
  const aux = scenes[1] || null;
  const key = isZh ? 'zh' : 'en';
  const ss = withSoundscape ? (aux ? main[key].ss + ' ' + aux[key].ss : main[key].ss) : 'N/A';
  const mu = withMusic ? main[key].mu : 'N/A';
  if (mode === 't2va') {
    $('f_scene').value = firstLine;
    $('f_soundscape').value = ss;
    $('f_music').value = mu;
  } else if (mode === 'i2va') {
    $('i2_first').value = raw;
    $('i2_action').value = '';
    $('i2_soundscape').value = ss;
    $('i2_music').value = mu;
  } else if (mode === 'fl2va') {
    $('fl_first').value = raw;
    $('fl_path').value = '';
    $('fl_last').value = '';
    $('fl_soundscape').value = ss;
    $('fl_music').value = mu;
  } else if (mode === 'l2va') {
    $('l2_last').value = raw;
    $('l2_opening').value = '';
    $('l2_path').value = '';
    $('l2_soundscape').value = ss;
    $('l2_music').value = mu;
  } else if (mode === 'ref2va') {
    $('r_subject').value = '';
    $('r_summary').value = raw;
    $('r_retention').value = '';
    $('r_detail').value = raw;
    $('r_soundscape').value = ss;
    $('r_music').value = mu;
  }
  generate();
  showToast('📝 离线模式：正文已按输入原样保留，并生成所选模式的 H3 结构');
}

